local Chandler = {}
local PRODUCTS = {
    oil_lamp = { name = "Oljenka", oilCost = 2, metalCost = 1, time = 2, cost = 30, lightRadius = 6, happiness = 1, description = "Preprosta oljna svetilka." },
    candle_lamp = { name = "Svečna svetilka", waxCost = 2, metalCost = 1, time = 2, cost = 25, lightRadius = 5, happiness = 1, description = "Svetilka za svečo." },
    chandelier = { name = "Luster", waxCost = 10, metalCost = 5, time = 14, cost = 300, lightRadius = 15, happiness = 8, prestige = 10, description = "Veliki luster." },
    lantern = { name = "Fenzar", oilCost = 3, metalCost = 2, time = 3, cost = 60, lightRadius = 8, happiness = 2, description = "Prenosni fenir." },
    torch = { name = "Bakla", oilCost = 1, woodCost = 1, time = 1, cost = 10, lightRadius = 4, description = "Preprosta bakla." },
    altar_light = { name = "Oltarna svetila", oilCost = 5, waxCost = 5, metalCost = 3, time = 7, cost = 200, lightRadius = 12, happiness = 3, faith = 15, description = "Svetila za cerkev." },
}
local BUILDINGS = {
    workshop = { name = "Svetilkarska delavnica", cost = { gold = 200, wood = 100, metal = 30 }, upkeep = 8, qualityBonus = 5 },
    lamp_shop = { name = "Svetilkarna", cost = { gold = 600, wood = 200, stone = 100, metal = 50 }, upkeep = 15, qualityBonus = 15 },
    oil_press = { name = "Stiskalnica olja", cost = { gold = 400, wood = 200, stone = 100 }, upkeep = 10, oilProduction = 5 },
    royal_chandlery = { name = "Kraljevska svetilkarna", cost = { gold = 3000, wood = 400, stone = 600, metal = 100 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
Chandler.oilStock = 15; Chandler.waxStock = 10; Chandler.metalStock = 10; Chandler.woodStock = 10
Chandler.productStock = {}; Chandler.buildings = {}; Chandler.chandler = nil; Chandler.activeMaking = {}; Chandler.totalProducts = 0; Chandler.dayTimer = 0
function Chandler.init() Chandler.oilStock=15; Chandler.waxStock=10; Chandler.metalStock=10; Chandler.woodStock=10; Chandler.productStock={}; Chandler.buildings={}; Chandler.chandler=nil; Chandler.activeMaking={}; Chandler.totalProducts=0; Chandler.dayTimer=0; print("[Chandler] Royal Chandler & Lamp Maker System initialized (6 products, 4 buildings)") end
function Chandler.hireChandler(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Chandler.chandler={name=n or ("Svetilkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilkar najet: %s (spretnost: %d)",Chandler.chandler.name,s),"success") end; return true end
function Chandler.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Chandler.build(id) local ok,e=Chandler.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Chandler.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Chandler.getQualityBonus() local b=0; for _,bd in ipairs(Chandler.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Chandler.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.oilCost and Chandler.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.waxCost and Chandler.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.metalCost and Chandler.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.woodCost and Chandler.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if #Chandler.buildings==0 then return false,"Potrebna delavnica" end; if not Chandler.chandler then return false,"Potreben svetilkar" end; return true end
function Chandler.make(pt) local ok,e=Chandler.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.oilCost then Chandler.oilStock=Chandler.oilStock-d.oilCost end; if d.waxCost then Chandler.waxStock=Chandler.waxStock-d.waxCost end; if d.metalCost then Chandler.metalStock=Chandler.metalStock-d.metalCost end; if d.woodCost then Chandler.woodStock=Chandler.woodStock-d.woodCost end; local t=d.time; if Chandler.chandler then t=math.max(1,t-math.floor(Chandler.chandler.skill/15)) end; table.insert(Chandler.activeMaking,{id="lamp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,lightRadius=d.lightRadius or 0,happiness=d.happiness or 0,prestige=d.prestige or 0,faith=d.faith or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function Chandler.completeMaking(m) local q=1.0+(Chandler.getQualityBonus()/100); if Chandler.chandler then q=q+(Chandler.chandler.skill/200) end; q=math.min(2.0,q); Chandler.productStock[m.productType]=(Chandler.productStock[m.productType] or 0)+1; Chandler.totalProducts=Chandler.totalProducts+1; if _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,m.faith) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if Chandler.chandler then Chandler.chandler.itemsMade=Chandler.chandler.itemsMade+1; if math.random()<0.15 then Chandler.chandler.skill=math.min(100,Chandler.chandler.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilka izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Chandler.update(dt) if not _G.state then return end; Chandler.dayTimer=Chandler.dayTimer+dt; if Chandler.dayTimer>=30 then Chandler.dayTimer=0; for i=#Chandler.activeMaking,1,-1 do local m=Chandler.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Chandler.completeMaking(m); table.remove(Chandler.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Chandler.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Chandler.chandler then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Chandler.getStats() return {oilStock=Chandler.oilStock,waxStock=Chandler.waxStock,metalStock=Chandler.metalStock,productStock=Chandler.productStock,numBuildings=#Chandler.buildings,hasChandler=Chandler.chandler~=nil,chandlerName=Chandler.chandler and Chandler.chandler.name or "—",chandlerSkill=Chandler.chandler and Chandler.chandler.skill or 0,activeMaking=#Chandler.activeMaking,totalProducts=Chandler.totalProducts} end
return Chandler
